import { z } from 'zod';

const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  age: z.number().min(18)
});

// Goal: Create a TypeScript type 'User' based on this schema.

const ConfigSchema = z.object({
  // API returns date as ISO string
  createdAt: z.string().datetime().transform((str) => new Date(str)),
  // API returns timeout in string "5000", we need number
  timeout: z.string().transform((str) => parseInt(str, 10))
});

type Config = z.infer<typeof ConfigSchema>;

interface User {
  id: string;
  name: string;
  // New field added later: email: string;
}

// Manually written Type Guard
function isUser(data: unknown): data is User {
  return typeof data === 'object' && data !== null && 'id' in data && 'name' in data;
}

function UserProfile({ userId }) {
  const [user, setUser] = useState(null);

  useEffect(() => {
    fetch(`/api/users/${userId}`)
      .then(res => res.json())
      .then(data => {
        // Validation inside UI Component
        const result = UserSchema.safeParse(data);
        if (result.success) setUser(result.data);
      });
  }, [userId]);

  if (!user) return <div>Loading...</div>;
  return <div>{user.name}</div>;
}

